<?php
declare(strict_types=1);
use Medbiohim\Http\Request;use Medbiohim\Http\Response;use Medbiohim\Http\Router;use Medbiohim\Middleware\RequireAuth;use Medbiohim\Middleware\RequireRole;use Medbiohim\Repositories\GroupRepository;use Medbiohim\Repositories\FileRepository;use Medbiohim\Repositories\HomeworkRepository;use Medbiohim\Repositories\SubjectRepository;use Medbiohim\Repositories\TestRepository;use Medbiohim\Repositories\UserRepository;use Medbiohim\Support\ContentStore;use Medbiohim\Support\Env;use Medbiohim\Services\SupabaseAuth;use Medbiohim\Services\SupabaseRest;
return static function(Router $router):void{
$adminGate=static function(Request $req):bool{if(!RequireAuth::handle($req))return false;return RequireRole::handle($req,['admin','moderator','teacher']);};$strictAdmin=static function(Request $req):bool{if(!RequireAuth::handle($req))return false;return RequireRole::handle($req,['admin']);};
$router->get('/api/v1/site',static function(Request $req,array $params):void{$store=new ContentStore();Response::success(['site'=>$store->getSite(),'announcements'=>$store->listAnnouncements()],$req->requestId);});
$router->post('/api/v1/admin/claim-admin',static function(Request $req,array $params):void{if(!RequireAuth::handle($req))return;$secret=trim((string)$req->json('secret',''));$expected=Env::get('ADMIN_BOOTSTRAP_SECRET','');$repo=new UserRepository();try{$repo->ensureProfile($req->user->id,$req->user->email??'');$rolesBefore=$repo->roleCodesForUser($req->user->id);if(in_array('admin',$rolesBefore,true)){Response::success(['roles'=>$rolesBefore,'message'=>'Admin role already granted','session_refresh_required'=>false],$req->requestId);return;}if($repo->countWithRole('admin')>0){Response::error('ADMIN_ALREADY_EXISTS','Admin already exists. Sign in with the configured administrator account.',$req->requestId,403);return;}if($expected===''||$secret===''||!hash_equals($expected,$secret)){Response::error('INVALID_BOOTSTRAP_SECRET','Bootstrap secret is invalid or not configured.',$req->requestId,403);return;}$repo->assignRole($req->user->id,'admin');$metadataSynced=(new SupabaseAuth())->setAppRole($req->user->id,'admin');$roles=$repo->roleCodesForUser($req->user->id);Response::success(['roles'=>$roles,'message'=>'Admin role granted','session_refresh_required'=>true,'metadata_synced'=>$metadataSynced],$req->requestId);}catch(\Throwable $e){Response::error('DB_ERROR','Could not assign role. Check the SpaceWeb → Supabase database connection.',$req->requestId,503);}});
$router->get('/api/v1/admin/users',static function(Request $req,array $params)use($strictAdmin):void{if(!$strictAdmin($req))return;try{Response::success(['items'=>(new UserRepository())->listUsers(100)],$req->requestId);}catch(\Throwable $e){try{Response::success(['items'=>SupabaseRest::listUsers(100)],$req->requestId);}catch(\Throwable $x){Response::error('DB_ERROR',$e->getMessage(),$req->requestId,503);}}});
$router->post('/api/v1/admin/users/roles',static function(Request $req,array $params)use($strictAdmin):void{if(!$strictAdmin($req))return;$userId=trim((string)$req->json('user_id',''));$role=trim((string)$req->json('role',''));$action=trim((string)$req->json('action','assign'));if($userId===''||$role===''){Response::error('VALIDATION_ERROR','user_id and role required',$req->requestId,422);return;}if(!in_array($role,['admin','moderator','teacher','student'],true)){Response::error('VALIDATION_ERROR','invalid role',$req->requestId,422);return;}try{$repo=new UserRepository();if($action==='revoke'){if($role==='admin'&&$userId===$req->user->id&&$repo->countWithRole('admin')<=1){Response::error('LAST_ADMIN','Cannot revoke the last administrator role.',$req->requestId,409);return;}$repo->revokeRole($userId,$role);}else{$repo->assignRole($userId,$role);}$roles=$repo->roleCodesForUser($userId);if($role==='admin')(new SupabaseAuth())->setAppRole($userId,in_array('admin',$roles,true)?'admin':null);Response::success(['roles'=>$roles,'session_refresh_required'=>$userId===$req->user->id&&$role==='admin'],$req->requestId);}catch(\Throwable $e){Response::error('DB_ERROR',$e->getMessage(),$req->requestId,503);}});
$router->post('/api/v1/admin/users/academic',static function(Request $req,array $params)use($strictAdmin):void{if(!$strictAdmin($req))return;$userId=trim((string)$req->json('user_id',''));$groupId=trim((string)$req->json('group_id',''));$semester=(int)$req->json('semester',0);if($userId===''||$groupId===''||$semester<1||$semester>12){Response::error('VALIDATION_ERROR','user_id, group_id and semester(1..12) are required',$req->requestId,422);return;}try{Response::success(['academic'=>(new UserRepository())->setAcademicContext($userId,$groupId,$semester)],$req->requestId);}catch(\InvalidArgumentException $e){Response::error('VALIDATION_ERROR',$e->getMessage(),$req->requestId,422);}catch(\Throwable $e){try{$user=(new UserRepository())->findById($userId);if($user===null){Response::error('NOT_FOUND','User not found',$req->requestId,404);return;} $group=SupabaseRest::getGroup($groupId);$g=is_array($group)?($group['group']??null):null;if(!is_array($g)){Response::error('NOT_FOUND','Group not found',$req->requestId,404);return;} Response::success(['academic'=>['user_id'=>$userId,'group_id'=>$groupId,'group_name'=>$g['name']??null,'group_code'=>$g['code']??null,'course_number'=>$g['course_number']??null,'semester'=>$semester]],$req->requestId);}catch(\Throwable $x){Response::error('DB_ERROR','Could not save user academic context',$req->requestId,503);}}});
$router->get('/api/v1/admin/overview',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req))return;$store=new ContentStore();$groups=$subjects=0;try{$groups=count((new GroupRepository())->listActive());$subjects=count((new SubjectRepository())->list(null,null));}catch(\Throwable $e){}Response::success(['site'=>$store->getSite(),'counts'=>['announcements'=>count($store->listAnnouncements()),'groups'=>$groups,'subjects'=>$subjects,'schedule'=>count($store->listSchedule()),'tests_local'=>count($store->listTestsLocal()),'curriculum'=>count($store->listCurriculum())]],$req->requestId);});
$router->put('/api/v1/admin/site',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req)||!RequireRole::handle($req,['admin','moderator']))return;$body=$req->jsonBody??[];$allowed=[];foreach(['title','subtitle','description','announcement_banner'] as $k)if(array_key_exists($k,$body))$allowed[$k]=is_string($body[$k])?$body[$k]:(string)$body[$k];if(isset($body['contacts'])&&is_array($body['contacts']))$allowed['contacts']=$body['contacts'];Response::success(['site'=>(new ContentStore())->updateSite($allowed)],$req->requestId);});
$router->get('/api/v1/admin/announcements',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req))return;Response::success(['items'=>(new ContentStore())->listAnnouncements()],$req->requestId);});
$router->post('/api/v1/admin/announcements',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req))return;$title=trim((string)$req->json('title',''));$body=trim((string)$req->json('body',''));if($title===''||$body===''){Response::error('VALIDATION_ERROR','title and body are required',$req->requestId,422);return;}Response::success(['item'=>(new ContentStore())->createAnnouncement(['title'=>$title,'body'=>$body,'pinned'=>(bool)$req->json('pinned',false)])],$req->requestId,201);});
$router->patch('/api/v1/admin/announcements/{id}',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req))return;$patch=[];foreach(['title','body','pinned'] as $k)if($req->jsonBody!==null&&array_key_exists($k,$req->jsonBody))$patch[$k]=$req->jsonBody[$k];$row=(new ContentStore())->updateAnnouncement($params['id'],$patch);if($row===null){Response::error('NOT_FOUND','Announcement not found',$req->requestId,404);return;}Response::success(['item'=>$row],$req->requestId);});
$router->delete('/api/v1/admin/announcements/{id}',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req))return;$ok=(new ContentStore())->deleteAnnouncement($params['id']);if(!$ok){Response::error('NOT_FOUND','Announcement not found',$req->requestId,404);return;}Response::success(['deleted'=>true],$req->requestId);});
$router->get('/api/v1/admin/curriculum',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req))return;Response::success(['items'=>(new ContentStore())->listCurriculum()],$req->requestId);});$router->put('/api/v1/admin/curriculum',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req))return;$items=$req->json('items');if(!is_array($items)){Response::error('VALIDATION_ERROR','items array required',$req->requestId,422);return;}Response::success(['items'=>(new ContentStore())->saveCurriculum($items)],$req->requestId);});
$router->get('/api/v1/admin/tests',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req))return;$store=new ContentStore();$local=$store->listTestsLocal();$db=[];try{$db=(new TestRepository())->listPublished(null);}catch(\Throwable $e){}Response::success(['items'=>$local,'db_items'=>$db],$req->requestId);});$router->put('/api/v1/admin/tests',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req))return;$items=$req->json('items');if(!is_array($items)){Response::error('VALIDATION_ERROR','items array required',$req->requestId,422);return;}$norm=[];foreach($items as $it){if(!is_array($it))continue;if(empty($it['id']))$it['id']=bin2hex(random_bytes(8));$norm[]=$it;}Response::success(['items'=>(new ContentStore())->saveTestsLocal($norm)],$req->requestId);});
$router->post('/api/v1/admin/tests/db',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req))return;$title=trim((string)$req->json('title',''));if($title===''){Response::error('VALIDATION_ERROR','title required',$req->requestId,422);return;}try{$row=(new TestRepository())->create(['title'=>$title,'description'=>(string)$req->json('description',''),'subject_id'=>$req->json('subject_id')?:null,'time_limit_sec'=>(int)($req->json('time_limit_sec',0)?:0)?:null,'is_published'=>(bool)$req->json('is_published',true)]);Response::success(['item'=>$row],$req->requestId,201);}catch(\Throwable $e){Response::error('DB_ERROR',$e->getMessage(),$req->requestId,503);}});
$router->get('/api/v1/admin/homeworks',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req)||!RequireRole::handle($req,['admin','moderator','teacher']))return;try{Response::success(['items'=>(new HomeworkRepository())->listAllForReview()],$req->requestId);}catch(\Throwable $e){try{Response::success(['items'=>SupabaseRest::listHomeworksForReview()],$req->requestId);}catch(\Throwable $x){Response::error('DB_ERROR','Could not load homeworks',$req->requestId,503);}}});
$router->post('/api/v1/admin/homeworks',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req)||!RequireRole::handle($req,['admin','moderator','teacher']))return;$title=trim((string)$req->json('title',''));if($title===''){Response::error('VALIDATION_ERROR','title is required',$req->requestId,422);return;}try{$row=(new HomeworkRepository())->create($title,$req->json('description')!==null?(string)$req->json('description'):null,$req->json('subject_id')?(string)$req->json('subject_id'):null,$req->json('group_id')?(string)$req->json('group_id'):null,$req->json('due_at')?(string)$req->json('due_at'):null,$req->user->id);Response::success(['item'=>$row],$req->requestId,201);}catch(\Throwable $e){try{$row=SupabaseRest::createHomework(['title'=>$title,'description'=>$req->json('description')!==null?(string)$req->json('description'):null,'subject_id'=>$req->json('subject_id')?(string)$req->json('subject_id'):null,'group_id'=>$req->json('group_id')?(string)$req->json('group_id'):null,'due_at'=>$req->json('due_at')?(string)$req->json('due_at'):null,'created_by'=>$req->user->id]);Response::success(['item'=>$row],$req->requestId,201);}catch(\Throwable $x){Response::error('DB_ERROR','Could not create homework',$req->requestId,503);}}});
$router->delete('/api/v1/admin/homeworks/{id}',static function(Request $req,array $params)use($adminGate):void{if(!$adminGate($req)||!RequireRole::handle($req,['admin','moderator']))return;try{$ok=(new HomeworkRepository())->delete($params['id']);if(!$ok){Response::error('NOT_FOUND','Homework not found',$req->requestId,404);return;}Response::success(['deleted'=>true],$req->requestId);}catch(\Throwable $e){Response::error('DB_ERROR','Could not delete homework',$req->requestId,503);}});
